const paths={cloud:'M6 18a5 5 0 0 1-1-9 7 7 0 0 1 13-1 5 5 0 0 1 0 10H6Z',folder:'M3 7V5a1 1 0 0 1 1-1h5l2 3h9a1 1 0 0 1 1 1v11a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V7Z',files:'M5 3h9l5 5v13H5V3Zm9 0v6h5M8 13h8M8 17h6',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 3a4 4 0 0 1 0 8m6 10v-2a4 4 0 0 0-3-3.87M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',shield:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Zm-4 9 3 3 5-6',upload:'M12 16V3m-4 4 4-4 4 4M4 15v5h16v-5',search:'m21 21-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0Z',plus:'M12 5v14M5 12h14',more:'M5 12h.01M12 12h.01M19 12h.01',chevron:'m9 5 7 7-7 7',down:'M12 3v12m-4-4 4 4 4-4M4 17v4h16v-4',close:'m6 6 12 12M6 18 18 6',lock:'M6 11h12v10H6V11Zm2 0V7a4 4 0 0 1 8 0v4',list:'M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01',grid:'M3 3h7v7H3V3Zm11 0h7v7h-7V3ZM3 14h7v7H3v-7Zm11 0h7v7h-7v-7Z',logout:'M9 21H3V3h6m7 4 5 5-5 5M8 12h13',menu:'M3 6h18M3 12h18M3 18h18',check:'m5 12 4 4L19 6',mail:'M3 5h18v14H3V5Zm0 1 9 7 9-7',move:'M3 7V4h6l3 3h9v13H3V7Zm4 6h10m-3-3 3 3-3 3',edit:'m15 5 4 4M3 21l5-1L21 7l-5-5L3 15v6Z',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7',info:'M12 11v6m0-10h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z'};
const icon=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.files}"/></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initials=name=>name.split(' ').map(n=>n[0]).slice(0,2).join('').toUpperCase();
const users=[{id:'admin',name:'Alex Morgan',email:'alex@oxygen.example',role:'Super User',active:true},{id:'emma',name:'Emma Wilson',email:'emma@oxygen.example',role:'Manager',active:true},{id:'daniel',name:'Daniel Murphy',email:'daniel@oxygen.example',role:'Contributor',active:true},{id:'sarah',name:'Sarah Collins',email:'sarah@oxygen.example',role:'Viewer',active:true}];
const folders=[{id:'clinical',name:'Clinical resources',parent:null,owner:'admin',grants:{emma:'Manager',daniel:'Contributor',sarah:'Viewer'}},{id:'operations',name:'Operations',parent:null,owner:'admin',grants:{emma:'Manager',daniel:'Contributor',sarah:'Viewer'}},{id:'team',name:'Team documents',parent:null,owner:'admin',grants:{emma:'Manager',daniel:'Contributor',sarah:'Viewer'}},{id:'brand',name:'Brand & marketing',parent:null,owner:'admin',grants:{emma:'Manager',daniel:'Contributor',sarah:'Viewer'}}];
const files=[{id:'f1',name:'Oxygen Therapy — Quick Reference.pdf',folder:'clinical',size:2400000,owner:'admin',date:'2026-09-30',ext:'pdf'},{id:'f2',name:'Equipment Register.xlsx',folder:'operations',size:846000,owner:'daniel',date:'2026-09-29',ext:'xlsx'},{id:'f3',name:'Team Onboarding Guide.docx',folder:'team',size:1200000,owner:'emma',date:'2026-09-28',ext:'docx'},{id:'f4',name:'Oxygen Care — Brand Assets.zip',folder:'brand',size:18500000,owner:'admin',date:'2026-09-27',ext:'zip'},{id:'f5',name:'Service Visit Checklist.pdf',folder:'operations',size:520000,owner:'emma',date:'2026-09-26',ext:'pdf'},{id:'f6',name:'Clinical Team — September.jpg',folder:'team',size:3800000,owner:'sarah',date:'2026-09-25',ext:'jpg'}];
let currentUser='admin',signedIn=true,page='files',currentFolder=null,query='',typeFilter='all',view='list';
const $=s=>document.querySelector(s);const user=()=>users.find(u=>u.id===currentUser);const rootFolder=id=>{let f=folders.find(f=>f.id===id);while(f?.parent)f=folders.find(x=>x.id===f.parent);return f};
const permission=id=>user()?.active?(user().role==='Super User'?'Super User':rootFolder(id)?.grants[currentUser]||null):null;
const can=(id,action)=>{const role=permission(id);return action==='view'?!!role:action==='upload'?['Super User','Manager','Contributor'].includes(role):['Super User','Manager'].includes(role)};
const formatSize=n=>n>=1e6?`${(n/1e6).toFixed(1)} MB`:n>=1000?`${Math.round(n/1000)} KB`:`${n} B`;
const avatar=id=>{const u=users.find(x=>x.id===id);return `<span class="avatar" title="${esc(u?.name||'User')}">${esc(initials(u?.name||'User'))}</span>`};
const badge=f=>`<span class="file-badge ${esc(f.ext)}">${icon('files')}<small>${esc(f.ext.toUpperCase().slice(0,4))}</small></span>`;
const brand=()=>`<div class="brand"><div class="brandmark">${icon('cloud')}</div><div><div class="wordmark">OCC</div><small>Oxygen Care Cloud</small></div></div>`;
const btn=(label,action,ic,primary=false)=>`<button type="button" class="btn ${primary?'primary':''}" data-action="${action}">${icon(ic)}${label}</button>`;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function visibleFiles(){return files.filter(f=>can(f.folder,'view')&&(!currentFolder||f.folder===currentFolder)&&(page!=='shared'||Object.keys(rootFolder(f.folder)?.grants||{}).length>0)&&f.name.toLowerCase().includes(query.toLowerCase())&&(typeFilter==='all'||(typeFilter==='documents'?['pdf','doc','docx','txt'].includes(f.ext):typeFilter==='images'?['png','jpg','jpeg','webp','gif','svg'].includes(f.ext):typeFilter==='spreadsheets'?['xlsx','xls','csv'].includes(f.ext):!['pdf','doc','docx','txt','png','jpg','jpeg','webp','gif','svg','xlsx','xls','csv'].includes(f.ext))));}
function render(){if(!signedIn){renderLogin();return}$('#app').innerHTML=`<button class="mobile-scrim" data-action="menu" aria-label="Close navigation"></button><aside class="sidebar">${brand()}<div class="nav-label">Workspace</div><nav aria-label="Main navigation"><button class="nav-button ${page==='files'?'active':''}" data-action="nav-files">${icon('folder')}My files<span class="count">${files.filter(f=>can(f.folder,'view')).length}</span></button><button class="nav-button ${page==='shared'?'active':''}" data-action="nav-shared">${icon('users')}Shared with me</button>${user().role==='Super User'?`<div class="nav-label">Administration</div><button class="nav-button ${page==='users'?'active':''}" data-action="nav-users">${icon('users')}User management</button>`:''}</nav><div class="sidebar-bottom"><div class="space-note"><strong>${icon('shield')} Your team's shared space</strong>Everything your team needs,<br>together in one place.</div><div class="profile">${avatar(currentUser)}<div><strong>${esc(user().name)}</strong><small>${esc(user().role)}</small></div><button data-action="logout" title="Sign out" aria-label="Sign out">${icon('logout')}</button></div></div></aside><div class="shell"><header class="topbar"><div class="top-label"><button class="icon-button mobile-menu" data-action="menu" aria-label="Open navigation">${icon('menu')}</button>${icon('cloud')}<span>Oxygen Care Cloud</span></div><div class="top-actions"><span class="demo-tag">Interactive prototype</span><label class="sr-only" for="role-preview">Preview account</label><select id="role-preview" class="role-select" aria-label="Preview account">${users.filter(u=>u.active).map(u=>`<option value="${u.id}" ${u.id===currentUser?'selected':''}>${esc(u.name)} · ${esc(u.role)}</option>`).join('')}</select></div></header><main class="content" id="main">${page==='users'?renderUsers():renderWorkspace()}</main></div>`;bind();}
function renderWorkspace(){const f=folders.find(f=>f.id===currentFolder);if(currentFolder&&!can(currentFolder,'view'))return `<div class="empty">${icon('lock')}<h1>Access restricted</h1><p>You no longer have access to this folder. Contact your Super User.</p><button class="btn" data-action="nav-files">Back to my files</button></div>`;const uploadable=currentFolder?can(currentFolder,'upload'):folders.some(f=>can(f.id,'upload'));const createable=currentFolder?can(currentFolder,'upload'):user().role==='Super User';const visibleFolders=folders.filter(f=>f.parent===currentFolder&&can(f.id,'view')&&(page!=='shared'||Object.keys(rootFolder(f.id)?.grants||{}).length));return `<div class="page-heading"><div><div class="eyebrow">Your workspace, connected</div><h1>${esc(f?.name||(page==='shared'?'Shared with me':'My files'))}</h1><p>${f?'A shared place for your team’s documents and resources.':page==='shared'?'The files and folders your team shares with you.':'A space for everything. A connection for everyone.'}</p></div><div class="actions">${createable?btn('New folder','new-folder','plus'):''}${uploadable?btn('Upload files','upload','upload',true):''}${f&&can(f.id,'manage')?btn('Share folder',`share:${f.id}`,'users'):''}</div></div>${currentFolder?breadcrumbs():`<div class="welcome-strip"><span class="strip-icon">${icon('shield')}</span><div><strong>Good work starts with the right information.</strong><p>Keep your files organised and give your team the access they need.</p></div><span class="access-pill">${icon('lock')}Access you control</span></div>`}${visibleFolders.length?`<section aria-label="Folders"><div class="section-heading"><h2>${currentFolder?'Folders':'Your folders'}</h2><span>${visibleFolders.length} folders</span></div><div class="folder-grid">${visibleFolders.map(f=>`<article class="folder-card"><div class="folder-top"><span class="folder-icon">${icon('folder')}</span>${can(f.id,'manage')?`<button class="icon-button" data-action="folder-menu:${f.id}" aria-label="Manage ${esc(f.name)}">${icon('more')}</button>`:''}</div><button class="folder-open" data-action="open-folder:${f.id}">${esc(f.name)}</button><div class="folder-meta"><span>${files.filter(x=>x.folder===f.id).length} files · ${permission(f.id)==='Super User'?'Owner':esc(permission(f.id))}</span><span class="people">${Object.keys(rootFolder(f.id).grants).slice(0,3).map(avatar).join('')}</span></div></article>`).join('')}</div></section>`:''}<section class="files-panel" aria-label="Files"><div class="files-toolbar"><h2>${currentFolder?'Files in this folder':'All files'} <span class="muted small" id="file-count"></span></h2><div class="tools"><label class="search">${icon('search')}<input id="search" type="search" placeholder="Search files…" aria-label="Search files" value="${esc(query)}"></label><select id="type-filter" class="select-filter" aria-label="Filter by file type">${[['all','All types'],['documents','Documents'],['images','Images'],['spreadsheets','Spreadsheets'],['other','Other files']].map(([v,l])=>`<option value="${v}" ${typeFilter===v?'selected':''}>${l}</option>`).join('')}</select><div class="view-switch" aria-label="File display"><button class="${view==='list'?'active':''}" data-action="view-list" aria-label="List view" aria-pressed="${view==='list'}">${icon('list')}</button><button class="${view==='grid'?'active':''}" data-action="view-grid" aria-label="Grid view" aria-pressed="${view==='grid'}">${icon('grid')}</button></div></div></div><div id="file-results">${renderFiles()}</div><div class="table-footer"><span id="results-label">${visibleFiles().length} files</span><span>Only files you have access to are shown</span></div></section>${uploadable?`<div class="drop-zone" id="drop-zone">${icon('cloud','upload-cloud')}<div><strong>Drag and drop files here, or <button class="text-button" data-action="upload">browse files</button></strong><p>Any file type · Kept in this tab for the demo · Up to 100 MB per file</p></div></div>`:''}<footer class="page-footer"><span>${icon('cloud')}OCC · Oxygen Care Cloud</span><span>Prototype workspace · Sample data · Changes reset on refresh</span></footer>`;}
function breadcrumbs(){let chain=[],f=folders.find(f=>f.id===currentFolder);while(f){chain.unshift(f);f=folders.find(x=>x.id===f.parent)}return `<nav class="breadcrumbs" aria-label="Folder path"><button data-action="nav-files">My files</button>${chain.map(f=>`${icon('chevron')}<button data-action="open-folder:${f.id}" ${f.id===currentFolder?'aria-current="page"':''}>${esc(f.name)}</button>`).join('')}</nav>`}
function renderFiles(){const list=visibleFiles();if(!list.length)return `<div class="empty">${icon(query?'search':'folder')}<h3>${query||typeFilter!=='all'?'No matching files':'Room for something useful'}</h3><p>${query||typeFilter!=='all'?'Try another search or file type.':'Files added to this folder will appear here.'}</p></div>`;if(view==='grid')return `<div class="grid-files">${list.map(f=>`<article class="grid-file">${badge(f)}<button class="file-name" data-action="file:${f.id}">${esc(f.name)}</button><div class="file-sub">${formatSize(f.size)} · ${esc(f.ext.toUpperCase())}</div><div class="actions">${avatar(f.owner)}<button class="icon-button" data-action="file:${f.id}" aria-label="Details for ${esc(f.name)}">${icon('more')}</button></div></article>`).join('')}</div>`;return `<div class="table-scroll"><table><thead><tr><th>Name</th><th class="optional-col">Owner</th><th>Last modified</th><th>Size</th><th>Access</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody>${list.map(f=>`<tr><td><div class="file-cell">${badge(f)}<div><button class="file-name" title="${esc(f.name)}" data-action="file:${f.id}">${esc(f.name)}</button><div class="file-sub">${esc(folders.find(x=>x.id===f.folder)?.name||'My files')}</div></div></div></td><td class="optional-col"><span class="owner-cell">${avatar(f.owner)}${f.owner===currentUser?'You':esc(users.find(u=>u.id===f.owner)?.name.split(' ')[0]||'User')}</span></td><td>${new Date(f.date+'T12:00:00').toLocaleDateString('en-IE',{day:'numeric',month:'short',year:'numeric'})}</td><td>${formatSize(f.size)}</td><td><span class="pill ${Object.keys(rootFolder(f.folder)?.grants||{}).length?'':'private'}">${icon(Object.keys(rootFolder(f.folder)?.grants||{}).length?'users':'lock')}${Object.keys(rootFolder(f.folder)?.grants||{}).length?'Shared':'Private'}</span></td><td><button class="icon-button" data-action="file:${f.id}" aria-label="Details for ${esc(f.name)}">${icon('more')}</button></td></tr>`).join('')}</tbody></table></div>`}
function updateFiles(){$('#file-results').innerHTML=renderFiles();$('#results-label').textContent=`${visibleFiles().length} files`;}
function renderUsers(){return `<div class="page-heading"><div><div class="eyebrow">Administration</div><h1>User management</h1><p>The right people. The right access.</p></div>${btn('Create user','create-user','plus',true)}</div><div class="notice users-intro">Accounts are created by a Super User. Folder permissions control what each person can access. This prototype uses sample accounts only.</div><section class="files-panel"><div class="files-toolbar"><h2>Your team</h2><span class="small muted">${users.filter(u=>u.active).length} active accounts</span></div><div class="table-scroll"><table><thead><tr><th>Name</th><th>Email</th><th>Account</th><th>Status</th><th>Actions</th></tr></thead><tbody>${users.map(u=>`<tr><td><div class="owner-cell">${avatar(u.id)}<strong>${esc(u.name)}</strong></div></td><td>${esc(u.email)}</td><td>${u.role==='Super User'?'Super User':'Standard user'}</td><td><span class="pill ${u.active?'':'private'}">${u.active?'Active':'Inactive'}</span></td><td><button class="btn" data-action="edit-user:${u.id}">Edit</button></td></tr>`).join('')}</tbody></table></div></section><div class="permission-key"><article><h3>Viewer</h3><p>View and download files in assigned folders.</p></article><article><h3>Contributor</h3><p>View, download, upload files, and create subfolders.</p></article><article><h3>Manager</h3><p>Contributor access plus organising, deleting, and sharing within assigned folders.</p></article></div>`}
function renderLogin(){$('#app').innerHTML=`<main class="login"><section class="login-art">${brand()}<div><div class="eyebrow">Oxygen Care Cloud</div><h1>A space for everything.<br>A connection for everyone.</h1><p>Your team's files, folders, and knowledge. Together in one thoughtfully organised workspace.</p></div><small>OCC · Interactive design prototype</small></section><section class="login-panel"><form class="login-form" id="login-form"><h2>Welcome back</h2><p>Sign in to your Oxygen Care workspace.</p><label class="field">Email address<input type="email" name="email" required value="alex@oxygen.example" autocomplete="username"></label><label class="field">Password<input type="password" name="password" required value="OCCdemo2026!" autocomplete="current-password"></label><div id="login-error" class="error" role="alert"></div><button class="btn primary" type="submit">Sign in ${icon('chevron')}</button><div class="demo-accounts"><p>Demo accounts · Password: <strong>OCCdemo2026!</strong><br>Use sample data only. This is not real authentication.</p><div class="role-choices">${users.filter(u=>u.active).map(u=>`<button type="button" data-demo="${u.id}">${esc(u.role)}</button>`).join('')}</div></div></form></section></main>`;$('#login-form').onsubmit=e=>{e.preventDefault();const data=new FormData(e.target);const u=users.find(u=>u.email.toLowerCase()===String(data.get('email')).trim().toLowerCase());if(!u||!u.active||data.get('password')!=='OCCdemo2026!'){$('#login-error').textContent='Email or password is incorrect, or this account is inactive.';return}currentUser=u.id;signedIn=true;page='files';currentFolder=null;render()};document.querySelectorAll('[data-demo]').forEach(b=>b.onclick=()=>{$('[name=email]').value=users.find(u=>u.id===b.dataset.demo).email;$('[name=password]').value='OCCdemo2026!'})}
function bind(){$('#role-preview').onchange=e=>{currentUser=e.target.value;page='files';currentFolder=null;query='';render();toast(`Previewing ${user().name}'s access`)};if($('#search'))$('#search').oninput=e=>{query=e.target.value;updateFiles()};if($('#type-filter'))$('#type-filter').onchange=e=>{typeFilter=e.target.value;updateFiles()};const drop=$('#drop-zone');if(drop){drop.ondragover=e=>{e.preventDefault();drop.classList.add('drag')};drop.ondragleave=()=>drop.classList.remove('drag');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('drag');startUpload([...e.dataTransfer.files])}}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const [action,id]=b.dataset.action.split(':');handleAction(action,id)});
function handleAction(action,id){if(action==='menu'){$('.sidebar')?.classList.toggle('open');$('.mobile-scrim')?.classList.toggle('open');return}if(action==='logout'){signedIn=false;render();return}if(action.startsWith('nav-')){page=action.slice(4);currentFolder=null;query='';typeFilter='all';if(page==='users'&&user().role!=='Super User')page='files';render();return}if(action==='open-folder'){currentFolder=id;query='';render();return}if(action.startsWith('view-')){view=action.slice(5);render();return}if(action==='close'){$('#modal').close();return}if(!signedIn||!user()?.active)return;if(action==='new-folder')return newFolder();if(action==='upload')return chooseUpload();if(action==='share')return shareFolder(id);if(action==='file')return fileDetails(id);if(action==='folder-menu')return folderMenu(id);if(action==='create-user')return editUser();if(action==='edit-user')return editUser(id);if(action==='rename-file')return renameItem(id,false);if(action==='rename-folder')return renameItem(id,true);if(action==='move-file')return moveItem(id,false);if(action==='move-folder')return moveItem(id,true);if(action==='delete-file')return deleteItem(id,false);if(action==='delete-folder')return deleteItem(id,true);if(action==='download')return downloadFile(id);}
let lastFocus=null,uploadTarget=null,uploading=false;
function openModal(title,body,footer='',onSubmit=null){const modal=$('#modal');if(!modal.open)lastFocus=document.activeElement;modal.innerHTML=`<form id="modal-form"><header class="modal-head"><h2 id="modal-title">${esc(title)}</h2><button type="button" class="icon-button" data-action="close" aria-label="Close dialog">${icon('close')}</button></header><div class="modal-body">${body}<div class="error" id="modal-error" role="alert"></div></div><footer class="modal-footer">${footer||'<button type="button" class="btn" data-action="close">Done</button>'}</footer></form>`;modal.setAttribute('aria-labelledby','modal-title');$('#modal-form').onsubmit=e=>{e.preventDefault();try{onSubmit?.(new FormData(e.target))}catch(err){$('#modal-error').textContent=err.message}};if(!modal.open)modal.showModal();setTimeout(()=>modal.querySelector('input,select,button')?.focus(),0);}
$('#modal').addEventListener('close',()=>{if(lastFocus?.isConnected)lastFocus.focus();else $('#main h1')?.focus()});
const modalButtons=(label='Save changes',danger=false)=>`<button type="button" class="btn" data-action="close">Cancel</button><button type="submit" class="btn ${danger?'danger':'primary'}">${label}</button>`;
const uid=prefix=>`${prefix}-${crypto.randomUUID()}`;
function validName(name){const n=String(name||'').trim();if(!n||n==='.'||n==='..'||/[\\/\x00-\x1f]/.test(n))throw Error('Enter a name without slashes or control characters.');if(n.length>160)throw Error('Use a name of 160 characters or fewer.');return n;}
function duplicate(name,container,folder,except){return(folder?folders:files).some(x=>x.id!==except&&(folder?x.parent:x.folder)===container&&x.name.toLowerCase()===name.toLowerCase());}
function createFolder(name,parent=currentFolder){if(parent?!can(parent,'upload'):user().role!=='Super User')throw Error('You do not have permission to create a folder here.');name=validName(name);if(duplicate(name,parent,true))throw Error('A folder with this name already exists here.');const f={id:uid('folder'),name,parent,owner:currentUser,grants:{}};folders.push(f);render();return f;}
function newFolder(){if(currentFolder?!can(currentFolder,'upload'):user().role!=='Super User')return toast('You do not have permission to create a folder here.');openModal('Create a folder',`<label class="field">Folder name<input name="name" placeholder="e.g. Service documentation" maxlength="160" required autofocus></label><p>${currentFolder?'This folder will inherit access from '+esc(rootFolder(currentFolder).name)+'.':'New top-level folders start private. Use Share folder to give your team access.'}</p>`,modalButtons('Create folder'),data=>{const f=createFolder(data.get('name'));$('#modal').close();toast(`“${f.name}” created`)});}
function folderMenu(id){const f=folders.find(x=>x.id===id);if(!f||!can(id,'manage'))return toast('You do not have permission to manage this folder.');openModal(f.name,`<p style="margin-bottom:15px">Manage this folder and everything inside it.</p><div style="display:grid;gap:10px">${btn('Manage sharing',`share:${id}`,'users')}${btn('Rename folder',`rename-folder:${id}`,'edit')}${btn('Move folder',`move-folder:${id}`,'move')}${btn('Delete folder',`delete-folder:${id}`,'trash')}</div>`);}
function shareFolder(id){const f=folders.find(x=>x.id===id);if(!f||!can(id,'manage'))return toast('You do not have permission to share this folder.');const root=rootFolder(id);const others=users.filter(u=>u.role!=='Super User'&&u.active);openModal('Manage folder access',`<div class="notice">${root.id!==id?`“${esc(f.name)}” inherits access from <strong>${esc(root.name)}</strong>. Changes here apply to that entire parent folder and its contents.`:`Access to <strong>${esc(root.name)}</strong> applies to all its files and subfolders.`}</div><p class="role-help">Viewer: view & download · Contributor: also upload & create folders · Manager: also organise, delete & share.</p>${users.filter(u=>u.role==='Super User'&&u.active).map(u=>`<div class="sharing-row">${avatar(u.id)}<div><strong>${esc(u.name)}</strong><small>${esc(u.email)}</small></div><span class="status">Super User</span></div>`).join('')}${others.map(u=>`<div class="sharing-row">${avatar(u.id)}<div><strong>${esc(u.name)}</strong><small>${esc(u.email)}</small></div><select name="grant-${u.id}" aria-label="Access for ${esc(u.name)}">${['No access','Viewer','Contributor','Manager'].map(role=>`<option value="${role}" ${(root.grants[u.id]||'No access')===role?'selected':''}>${role}</option>`).join('')}</select></div>`).join('')}${!others.length?'<p>No standard users yet. Create users in User management.</p>':''}`,modalButtons('Save access'),data=>{if(!can(id,'manage'))throw Error('Your permission to manage this folder has changed.');for(const u of others){const role=data.get('grant-'+u.id);if(role==='No access')delete root.grants[u.id];else if(['Viewer','Contributor','Manager'].includes(role))root.grants[u.id]=role;}$('#modal').close();render();toast('Folder access updated');});}
function fileDetails(id){const f=files.find(x=>x.id===id);if(!f||!can(f.folder,'view'))return toast('This file is unavailable or you do not have access.');const safeImage=f.url&&['png','jpg','jpeg','webp','gif','avif','bmp'].includes(f.ext);const preview=safeImage?`<img src="${esc(f.url)}" alt="${esc(f.name)}">`:f.url&&f.ext==='pdf'?`<iframe src="${esc(f.url)}" title="Preview of ${esc(f.name)}" sandbox></iframe>`:badge(f);openModal(f.name,`<div class="detail-preview">${preview}</div>${!f.url?'<div class="notice">Sample file record. Download provides a clearly labelled sample note. Upload your own image or PDF to try a real preview.</div>':!safeImage&&f.ext!=='pdf'?'<div class="notice">This file type is stored for this demo. Download it to open with a compatible application.</div>':''}<dl class="details"><dt>File type</dt><dd>${esc(f.ext.toUpperCase()||'FILE')}</dd><dt>Size</dt><dd>${formatSize(f.size)}</dd><dt>Folder</dt><dd>${esc(folders.find(x=>x.id===f.folder)?.name)}</dd><dt>Uploaded by</dt><dd>${esc(users.find(u=>u.id===f.owner)?.name)}</dd><dt>Your access</dt><dd>${esc(permission(f.folder))} · inherited from folder</dd></dl>${can(f.folder,'manage')?`<div class="actions" style="margin-top:24px;flex-wrap:wrap">${btn('Rename',`rename-file:${id}`,'edit')}${btn('Move',`move-file:${id}`,'move')}${btn('Delete',`delete-file:${id}`,'trash')}${btn('Folder access',`share:${f.folder}`,'users')}</div>`:''}`,`<button class="btn" type="button" data-action="close">Close</button><button class="btn primary" type="button" data-action="download:${id}">${icon('down')}${f.url?'Download file':'Download sample note'}</button>`);}
function downloadFile(id){const f=files.find(x=>x.id===id);if(!f||!can(f.folder,'view'))return toast('You do not have permission to download this file.');const url=f.url||URL.createObjectURL(new Blob([`OCC Oxygen Care Cloud — prototype sample\n\n${f.name}\n\nThis is a sample note, not the original document. The file list contains demonstration records. Upload your own file to try original-file downloads.\n`],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download=f.url?f.name:`${f.name}.sample-note.txt`;a.click();if(!f.url)setTimeout(()=>URL.revokeObjectURL(url),5000);toast(f.url?'Download started':'Sample note downloaded');}
function renameItem(id,isFolder){const item=(isFolder?folders:files).find(x=>x.id===id);const access=isFolder?id:item?.folder;if(!item||!can(access,'manage'))return toast('You do not have permission to rename this item.');openModal(`Rename ${isFolder?'folder':'file'}`,`<label class="field">Name<input name="name" value="${esc(item.name)}" maxlength="160" required></label>`,modalButtons('Rename'),data=>{if(!can(access,'manage'))throw Error('Your access has changed.');const name=validName(data.get('name'));if(duplicate(name,isFolder?item.parent:item.folder,isFolder,id))throw Error('An item with this name already exists here.');item.name=name;if(!isFolder)item.ext=name.includes('.')?name.split('.').pop().toLowerCase():'';$('#modal').close();render();toast('Name updated');});}
function descendants(id){const result=[id];for(let i=0;i<result.length;i++)for(const f of folders)if(f.parent===result[i])result.push(f.id);return result;}
function moveItem(id,isFolder){const item=(isFolder?folders:files).find(x=>x.id===id);if(!item||!can(isFolder?id:item.folder,'manage'))return toast('You do not have permission to move this item.');const excluded=isFolder?descendants(id):[];const candidates=folders.filter(f=>can(f.id,'upload')&&!excluded.includes(f.id)&&(isFolder?item.parent!==f.id:item.folder!==f.id));const allowRoot=isFolder&&user().role==='Super User'&&item.parent!==null;openModal(`Move ${isFolder?'folder':'file'}`,`<p style="margin-bottom:18px">Choose a destination for <strong>${esc(item.name)}</strong>. This item will inherit the destination folder’s access.</p><label class="field">Destination<select name="destination" required><option value="" disabled selected>Select a folder</option>${allowRoot?'<option value="__root">My files (top level)</option>':''}${candidates.map(f=>`<option value="${f.id}">${esc(folderPath(f.id))}</option>`).join('')}</select></label>${!candidates.length&&!allowRoot?'<p>No other folders are available with upload access.</p>':''}`,modalButtons('Move here'),data=>{const dest=data.get('destination');if(!dest)throw Error('Select a destination.');const target=dest==='__root'?null:dest;if(!can(isFolder?id:item.folder,'manage')||(target?!can(target,'upload'):!allowRoot))throw Error('You do not have permission to move this item here.');if(isFolder&&excluded.includes(target))throw Error('A folder cannot be moved inside itself.');if(duplicate(item.name,target,isFolder,id))throw Error('An item with this name already exists at the destination.');if(isFolder){item.parent=target;item.grants={};}else item.folder=target;$('#modal').close();render();toast('Item moved. Destination access now applies.');});}
function folderPath(id){let f=folders.find(x=>x.id===id),names=[];while(f){names.unshift(f.name);f=folders.find(x=>x.id===f.parent)}return names.join(' / ');}
function deleteItem(id,isFolder){const item=(isFolder?folders:files).find(x=>x.id===id);if(!item||!can(isFolder?id:item.folder,'manage'))return toast('You do not have permission to delete this item.');const ids=isFolder?descendants(id):[];const count=isFolder?files.filter(f=>ids.includes(f.folder)).length:1;openModal(`Delete ${isFolder?'folder':'file'}?`,`<p>Delete <strong>${esc(item.name)}</strong>${isFolder?`, including ${ids.length-1} subfolders and ${count} files`:''} from this demo?</p><p style="margin-top:12px">This cannot be undone within the current session. Refreshing restores the original sample data.</p>`,modalButtons('Delete',true),()=>{if(!can(isFolder?id:item.folder,'manage'))throw Error('Your access has changed.');for(let i=files.length-1;i>=0;i--)if(isFolder?ids.includes(files[i].folder):files[i].id===id){if(files[i].url)URL.revokeObjectURL(files[i].url);files.splice(i,1)}if(isFolder)for(let i=folders.length-1;i>=0;i--)if(ids.includes(folders[i].id))folders.splice(i,1);if(ids.includes(currentFolder))currentFolder=item.parent;$('#modal').close();render();toast(`${isFolder?'Folder':'File'} deleted`);});}
function editUser(id){if(user().role!=='Super User')return toast('Only a Super User can manage accounts.');const u=users.find(x=>x.id===id);const roots=folders.filter(f=>!f.parent);openModal(u?'Edit user':'Create user',`<label class="field">Full name<input name="name" value="${esc(u?.name||'')}" required maxlength="80" placeholder="e.g. Jamie Kelly"></label><label class="field">Email address<input name="email" type="email" value="${esc(u?.email||'')}" required placeholder="jamie@example.com"></label><label class="field">Account type<select name="account"><option value="standard" ${u?.role!=='Super User'?'selected':''}>Standard user</option><option value="super" ${u?.role==='Super User'?'selected':''}>Super User — full workspace access</option></select></label>${u?`<label class="field">Status<select name="status"><option value="active" ${u.active?'selected':''}>Active</option><option value="inactive" ${!u.active?'selected':''}>Inactive</option></select></label>`:''}<h3 style="margin:20px 0 10px">Folder access</h3><p class="role-help">Standard users only. Super Users automatically have full access.</p>${roots.map(f=>`<div class="sharing-row"><span class="folder-icon" style="width:30px;height:30px">${icon('folder')}</span><strong>${esc(f.name)}</strong><select name="folder-${f.id}" aria-label="Access to ${esc(f.name)}">${['No access','Viewer','Contributor','Manager'].map(r=>`<option ${(u&&f.grants[u.id]||'No access')===r?'selected':''}>${r}</option>`).join('')}</select></div>`).join('')}<p style="margin-top:18px">Demo password: <strong>OCCdemo2026!</strong>. No invitation email is sent.</p>`,modalButtons(u?'Save user':'Create user'),data=>{if(user().role!=='Super User')throw Error('Super User access required.');const name=String(data.get('name')).trim(),email=String(data.get('email')).trim().toLowerCase(),superUser=data.get('account')==='super',active=data.get('status')!=='inactive';if(!name||name.length>80)throw Error('Enter a name of 1–80 characters.');if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))throw Error('Enter a valid email address.');if(users.some(x=>x.id!==id&&x.email.toLowerCase()===email))throw Error('This email address already has an account.');if(id===currentUser&&(!active||!superUser))throw Error('You cannot deactivate or remove Super User access from the account you are using.');if(u?.role==='Super User'&&(!superUser||!active)&&users.filter(x=>x.role==='Super User'&&x.active&&x.id!==id).length===0)throw Error('Keep at least one active Super User.');const record=u||{id:uid('user')};record.name=name;record.email=email;record.active=active;record.role=superUser?'Super User':'Viewer';for(const f of roots){const grant=data.get('folder-'+f.id);if(grant==='No access'||superUser)delete f.grants[record.id];else if(['Viewer','Contributor','Manager'].includes(grant)){f.grants[record.id]=grant;if(!superUser&&['Viewer','Contributor','Manager'].indexOf(grant)>['Viewer','Contributor','Manager'].indexOf(record.role))record.role=grant;}}if(!u)users.push(record);$('#modal').close();render();toast(u?'User updated':'Demo user created');});}
function writableFolders(){return folders.filter(f=>can(f.id,'upload'));}
function chooseUpload(){if(uploading)return toast('An upload is already in progress.');if(currentFolder){if(!can(currentFolder,'upload'))return toast('You do not have upload access here.');uploadTarget=currentFolder;$('#file-input').click();return}const options=writableFolders();if(!options.length)return toast('Create a folder or ask your Super User for upload access.');openModal('Choose an upload folder',`<p style="margin-bottom:18px">Files inherit the access of the folder you upload to.</p><label class="field">Upload to<select name="destination">${options.map(f=>`<option value="${f.id}">${esc(folderPath(f.id))}</option>`).join('')}</select></label>`,modalButtons('Choose files'),data=>{uploadTarget=data.get('destination');if(!can(uploadTarget,'upload'))throw Error('You do not have upload access to this folder.');$('#modal').close();$('#file-input').click();});}
$('#file-input').onchange=e=>{const picked=[...e.target.files];e.target.value='';if(picked.length)startUpload(picked,uploadTarget)};
function startUpload(picked,target=currentFolder){if(!picked.length)return;if(uploading)return toast('An upload is already in progress.');if(!target){const choices=writableFolders();if(!choices.length)return toast('You do not have a folder with upload access.');openModal('Choose an upload folder',`<p style="margin-bottom:18px">${picked.length} file${picked.length===1?'':'s'} ready to add.</p><label class="field">Upload to<select name="destination">${choices.map(f=>`<option value="${f.id}">${esc(folderPath(f.id))}</option>`).join('')}</select></label>`,modalButtons('Add files'),data=>startUpload(picked,data.get('destination')));return}if(!can(target,'upload'))return toast('You do not have upload access to this folder.');uploading=true;const actor=currentUser;openModal('Adding files',`<div class="notice">Files stay in memory in this browser tab. This simulates a cloud upload; refreshing clears uploaded files.</div><div id="upload-list">${picked.map((f,i)=>`<div class="upload-item" id="up-${i}"><header><span>${esc(f.name)}</span><span>${formatSize(f.size)}</span></header><div class="progress"><span style="width:0%"></span></div><div class="upload-status">Waiting…</div></div>`).join('')}</div>`,'<button type="button" class="btn" data-action="close">Close</button>');(async()=>{let added=0;for(let i=0;i<picked.length;i++){const f=picked[i];let failure='';try{validName(f.name);if(f.size>100000000)throw Error('Exceeds the 100 MB prototype limit.');if(duplicate(f.name,target,false))throw Error('A file with this name already exists. Rename it and try again.');if(actor!==currentUser||!signedIn||!can(target,'upload')||!folders.some(x=>x.id===target))throw Error('The destination is unavailable or access has changed.');for(const progress of [30,65,100]){const row=$('#up-'+i);if(row){row.querySelector('.progress span').style.width=progress+'%';row.querySelector('.upload-status').textContent=progress===100?'Added to this demo':'Preparing file…'}await new Promise(resolve=>setTimeout(resolve,120))}if(actor!==currentUser||!signedIn||!can(target,'upload'))throw Error('Access changed while adding this file.');files.unshift({id:uid('file'),name:f.name,folder:target,size:f.size,owner:actor,date:new Date().toISOString().slice(0,10),ext:f.name.includes('.')?f.name.split('.').pop().toLowerCase():'',url:URL.createObjectURL(f)});added++;}catch(err){failure=err.message;const row=$('#up-'+i);if(row){row.querySelector('.upload-status').textContent=failure;row.querySelector('.upload-status').style.color='#b43c50';row.querySelector('.progress span').style.background='#d57987'}}}uploading=false;render();if($('#modal').open&&$('#upload-list'))$('#modal-title').textContent=added===picked.length?'Files added':'Upload complete';toast(`${added} of ${picked.length} files added${added<picked.length?' · Some files could not be added':''}`);})();}
if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});const registerPrototypeTool=tool=>Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(error=>console.info('Optional browser tools unavailable:',error.message));try{registerPrototypeTool({name:'list_occ_files',description:'List files visible to the currently previewed OCC account in the current folder. Read only; this is sample prototype state.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:input=>{if(input&&Object.keys(input).length)throw Error('No arguments are accepted.');if(!signedIn)throw Error('Sign in to a demo account first.');return {files:visibleFiles().map(f=>({id:f.id,name:f.name,folder:f.folder,size:f.size})),prototype:true}}});registerPrototypeTool({name:'create_occ_folder',description:'Create a folder in the current OCC prototype location with the same permission checks as the interface. Session-only state.',inputSchema:{type:'object',properties:{name:{type:'string'}},required:['name'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!signedIn||!input||typeof input.name!=='string'||Object.keys(input).some(k=>k!=='name'))throw Error('A name string is required.');const f=createFolder(input.name);toast(`“${f.name}” created`);return {id:f.id,name:f.name,prototype:true}}});}catch(error){console.info('Optional browser tools unavailable:',error.message)}}
render();
